sql.where:
v.del_yn = 'N'
AND v.visit_type IN (SELECT code_id FROM tb_common WHERE cmm_id = 'PT' AND code_tag = #{codeTag})
AND v.status_code = #{statusCode}
AND ( v.company_name LIKE '%' + #{keyword} + '%' OR v.work_purpose LIKE '%' + #{keyword} + '%' OR EXISTS (SELECT 1 FROM tb_visit_car vc JOIN tb_car car ON car.car_id = vc.car_id WHERE vc.visit_no = v.visit_no AND car.car_no LIKE '%' + #{keyword} + '%') OR EXISTS (SELECT 1 FROM tb_visit_person vp JOIN tb_card cd ON cd.person_id = vp.person_id WHERE vp.visit_no = v.visit_no AND cd.del_yn = 'N' AND cd.biostar_card_value LIKE '%' + #{keyword} + '%') OR EXISTS (SELECT 1 FROM tb_visit_car vc2 JOIN tb_card cd2 ON cd2.car_id = vc2.car_id WHERE vc2.visit_no = v.visit_no AND cd2.del_yn = 'N' AND cd2.biostar_card_value LIKE '%' + #{keyword} + '%')
OR EXISTS (SELECT 1 FROM tb_visit_person vp2 JOIN tb_person pr ON pr.person_id = vp2.person_id WHERE vp2.visit_no = v.visit_no AND pr.person_name = #{keywordEnc}) OR EXISTS (SELECT 1 FROM tb_visit_manager vm JOIN tb_person pm ON pm.person_id = vm.person_id WHERE vm.visit_no = v.visit_no AND pm.person_name = #{keywordEnc})
)
